/**
 * Bundled library seed — snapshot of the curator's public Spotify profile
 * (data/library-seed.json, generated by scripts/build_library_seed.mjs).
 * Tracks carry MIR features measured locally on public audio previews
 * (tempo, loudness, beat clarity, brightness → energy/valence per thesis §7.5).
 */

import { enrichTrackAudioFeatures } from './track-energy.js';

const SEED_PATH = 'data/library-seed.json';

/** @type {{ tracks: object[], artistCounts: object }|null} */
let cache = null;

/**
 * Load and normalize the bundled seed.
 * @returns {Promise<{ tracks: object[], artistCounts: object, profileUrl: string|null }>}
 */
export async function loadLibrarySeed() {
  if (cache) return cache;
  const url = chrome.runtime.getURL(SEED_PATH);
  const res = await fetch(url);
  if (!res.ok) throw new Error(`SEED_HTTP_${res.status}`);
  const seed = await res.json();
  const tracks = (seed.tracks || []).map((t) =>
    enrichTrackAudioFeatures({
      genre: null,
      genres: [],
      youtubeVideoId: null,
      ...t,
    }),
  );
  cache = {
    tracks,
    artistCounts: seed.artistCounts || {},
    profileUrl: seed.profileUrl || null,
  };
  return cache;
}

/**
 * MIR feature lookup by spotify id (used to re-attach measured features to
 * freshly synced tracks that only carry embed metadata).
 * @returns {Promise<Map<string, object>>}
 */
export async function seedFeatureMap() {
  const { tracks } = await loadLibrarySeed();
  const map = new Map();
  for (const t of tracks) {
    if (!t.id) continue;
    map.set(t.id, {
      tempo: t.tempo ?? null,
      loudness: t.loudness ?? null,
      danceability: t.danceability ?? null,
      acousticness: t.acousticness ?? null,
      energy: t.energy ?? null,
      valence: t.valence ?? null,
      energySource: t.energySource || 'mir_preview',
      valenceSource: t.valenceSource || 'mir_preview',
    });
  }
  return map;
}
